    "art82Desc": "• કલમ 82: લોકોના ગૃહમાં બેઠકોની ફાળવણીનું પુન: ગોઠવણ અને દરેક રાજ્યને પ્રાદેશિક મતવિસ્તારમાં વિભાજન.",
    "art170_2Desc": "• અનુચ્છેદ 170(2): દરેક રાજ્ય વિધાનસભાને પ્રાદેશિક મતવિસ્તારમાં વિભાજિત કરવામાં આવે છે જેમ કે વસ્તી: બેઠકોનો ગુણોત્તર વ્યવહારીક રીતે સમાન હોય છે.",
    "art330_332Desc": "• અનુચ્છેદ 330 અને 332: અનુસૂચિત જાતિ અને અનુસૂચિત જનજાતિ માટે ફરજિયાત પ્રમાણસર અનામત.",
    "delimActSec9Desc": "• સીમાંકન અધિનિયમ કલમ 9: સમાન વસ્તી વિચલન બાઉન્ડ (±10%), ભૌતિક લક્ષણો અને વહીવટી એકમ અખંડિતતા.",
    "art170Desc": "• અનુચ્છેદ 170: આદેશ કે રાજ્યની અંદર દરેક મતવિસ્તારમાં કડક ±10% વિચલન બાઉન્ડમાં સમાન વસ્તી હોવી જોઈએ.",
    "art330Desc": "• અનુચ્છેદ 330 અને 332: અનુસૂચિત જાતિ અને અનુસૂચિત જનજાતિ માટે પ્રમાણસર અનામત તાજેતરની પ્રકાશિત વસ્તી ગણતરીના આંકડાઓના આધારે.",
    "publicObjectionDesc": "• પબ્લિક ઓબ્જેક્શન વિન્ડો: સીમાંકન અધિનિયમની કલમ 9(2) હેઠળ, કમિશને ડ્રાફ્ટ બાઉન્ડ્રી પ્રકાશિત કરવી જોઈએ અને નાગરિકોને અંતિમ સૂચના પહેલાં વાંધાઓ સબમિટ કરવાની મંજૂરી આપવી જોઈએ.",
